<?php require '../includes/db.php';require '../includes/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$st=$_POST['status'];if(in_array($st,['Pending','Shipped','Delivered'],true)){$s=$conn->prepare('UPDATE orders SET status=? WHERE id=?');$s->bind_param('si',$st,$id);$s->execute();}}$rows=$conn->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC');$page_title='Orders';include '../includes/header.php';?><h1>Manage Orders</h1><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Update</th></tr><?php while($x=$rows->fetch_assoc()):?><tr><td>#<?=$x['id']?></td><td><?=e($x['name'])?></td><td><?=cash($x['total'])?></td><td><?=e($x['status'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="status"><?php foreach(['Pending','Shipped','Delivered'] as $v):?><option <?=$v===$x['status']?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn">Save</button></form></td></tr><?php endwhile;?></table><?php include '../includes/footer.php';?>
